CREATE TABLE public.ca_daily_bonus_days (
    user_id uuid NOT NULL,
    bonus_date date NOT NULL,
    streak integer NOT NULL,
    cycle_day integer NOT NULL,
    streak_day integer,
    tiles jsonb NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    first_claimed_at timestamp with time zone,
    sheet_shown_at timestamp with time zone,
    streak_protected boolean DEFAULT false NOT NULL,
    shield_consumed_id uuid,
    CONSTRAINT ca_daily_bonus_days_cycle_day_check CHECK (((cycle_day >= 1) AND (cycle_day <= 7))),
    CONSTRAINT ca_daily_bonus_days_streak_check CHECK ((streak >= 1))
);
