    is_welcome boolean DEFAULT false NOT NULL
);
CREATE TABLE public.ca_daily_bonus_calendar (
    id bigint NOT NULL,
    cycle_day integer,
    streak_day integer,
    slot integer NOT NULL,
    kind text NOT NULL,
    quantity integer DEFAULT 0 NOT NULL,
    diamonds integer DEFAULT 0 NOT NULL,
    vip_only boolean DEFAULT false NOT NULL,
    label text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ca_daily_bonus_calendar_cycle_day_check CHECK (((cycle_day >= 1) AND (cycle_day <= 7))),
    CONSTRAINT ca_daily_bonus_calendar_diamonds_check CHECK (((diamonds >= 0) AND (diamonds <= 125))),
    CONSTRAINT ca_daily_bonus_calendar_kind_check CHECK ((kind = ANY (ARRAY['diamonds'::text, 'throwables'::text, 'rabbit_hunts'::text, 'time_bank'::text, 'mystery'::text, 'shield'::text, 'boost'::text]))),
    CONSTRAINT ca_daily_bonus_calendar_kind_shape CHECK ((((kind = 'diamonds'::text) AND (diamonds > 0) AND (quantity = 0)) OR ((kind = ANY (ARRAY['throwables'::text, 'rabbit_hunts'::text, 'time_bank'::text])) AND (quantity > 0) AND (diamonds = 0)) OR ((kind = 'mystery'::text) AND (quantity = 0) AND (diamonds = 0)) OR ((kind = 'shield'::text) AND (quantity > 0) AND (diamonds = 0)) OR ((kind = 'boost'::text) AND (quantity > 0) AND (diamonds = 0)))),
    CONSTRAINT ca_daily_bonus_calendar_one_axis CHECK (((cycle_day IS NULL) <> (streak_day IS NULL))),
    CONSTRAINT ca_daily_bonus_calendar_quantity_check CHECK ((quantity >= 0)),
    CONSTRAINT ca_daily_bonus_calendar_slot_check CHECK (((slot >= 1) AND (slot <= 6))),
    CONSTRAINT ca_daily_bonus_calendar_streak_day_check CHECK ((streak_day >= 8))
);
