    ends_at timestamp with time zone NOT NULL,
    source text DEFAULT 'daily_bonus'::text NOT NULL,
    claim_id uuid,
    applications integer DEFAULT 0 NOT NULL,
    applied_diamonds integer DEFAULT 0 NOT NULL,
    last_applied_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT player_boosts_factor_check CHECK (((factor > 1.00) AND (factor <= 5.00))),
    CONSTRAINT player_boosts_kind_check CHECK ((kind = 'mission_diamonds'::text)),
    CONSTRAINT player_boosts_source_check CHECK ((source = ANY (ARRAY['daily_bonus'::text, 'admin'::text]))),
    CONSTRAINT player_boosts_window CHECK ((ends_at > starts_at))
);
CREATE TABLE public.wheel_configs (
    host_id uuid NOT NULL,
    host_kind text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    spin_price_diamonds integer DEFAULT 100 NOT NULL,
    segment_version integer NOT NULL,
    exposure_allowance_chips numeric(14,2) DEFAULT 500 NOT NULL,
    purchased_only boolean DEFAULT true NOT NULL,
    allow_fixture_accounts boolean DEFAULT false NOT NULL,
    max_spins_per_player_per_day integer DEFAULT 200 NOT NULL,
    min_seconds_between_spins integer DEFAULT 3 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    diamond_seed integer DEFAULT 2500 NOT NULL,
    welcome_spin_enabled boolean DEFAULT true NOT NULL,
    welcome_budget_chips numeric DEFAULT 0 NOT NULL,
    welcome_budget_period_days integer DEFAULT 30 NOT NULL,
    CONSTRAINT wheel_configs_diamond_seed_check CHECK ((diamond_seed >= 0)),
    CONSTRAINT wheel_configs_exposure_allowance_chips_check CHECK ((exposure_allowance_chips >= (0)::numeric)),
    CONSTRAINT wheel_configs_host_kind_check CHECK ((host_kind = ANY (ARRAY['union'::text, 'club'::text]))),
    CONSTRAINT wheel_configs_max_spins_per_player_per_day_check CHECK ((max_spins_per_player_per_day > 0)),
    CONSTRAINT wheel_configs_min_seconds_between_spins_check CHECK ((min_seconds_between_spins >= 0)),
    CONSTRAINT wheel_configs_spin_price_diamonds_check CHECK ((spin_price_diamonds > 0)),
    CONSTRAINT wheel_configs_welcome_period_nonneg CHECK ((welcome_budget_period_days >= 0))
);
CREATE TABLE public.wheel_pools (
    host_id uuid NOT NULL,
