    chips_paid numeric(16,2) DEFAULT 0 NOT NULL,
    diamond_float numeric(16,4) DEFAULT 0 NOT NULL,
    diamonds_paid numeric(18,0) DEFAULT 0 NOT NULL,
    constrained_spins bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    diamond_seed numeric(16,4) DEFAULT 0 NOT NULL,
    welcome_chips_paid numeric DEFAULT 0 NOT NULL,
    welcome_spins integer DEFAULT 0 NOT NULL,
    CONSTRAINT wheel_pools_diamond_float_check CHECK ((diamond_float >= (0)::numeric)),
    CONSTRAINT wheel_pools_diamond_seed_check CHECK ((diamond_seed >= (0)::numeric)),
    CONSTRAINT wheel_pools_mint_carry_check CHECK (((mint_carry >= (0)::numeric) AND (mint_carry < 0.01)))
);
