    weight integer NOT NULL,
    CONSTRAINT wheel_segments_amount_check CHECK (((amount >= (0)::numeric) AND (amount = round(amount, 2)))),
    CONSTRAINT wheel_segments_check CHECK (((kind = 'nothing'::text) = (amount = (0)::numeric))),
    CONSTRAINT wheel_segments_check1 CHECK (((kind <> 'diamonds'::text) OR (amount = round(amount, 0)))),
    CONSTRAINT wheel_segments_kind_check CHECK ((kind = ANY (ARRAY['nothing'::text, 'chips'::text, 'diamonds'::text]))),
    CONSTRAINT wheel_segments_ord_check CHECK ((ord > 0)),
    CONSTRAINT wheel_segments_weight_check CHECK ((weight > 0))
);
